html:
{%- set TITLE = "BILL OF QUANTITIES" -%}{%- set TITLE_AR = "جدول الكميات" -%}
{%- import "altor_project/templates/print/altor_print.html" as ap with context -%}
{%- set c = altor_company(doc.company, doc) -%}
{{ ap.styles(c) }}
{%- set p = altor_party(doc) -%}
{%- set groups = altor_boq(doc, True) -%}
<div class="ap">
{{ ap.header(c, TITLE, TITLE_AR, [
    ["Ref. No.", doc.name],
    ["Date", ap.date(doc.transaction_date)],
    ["Valid Till", ap.date(doc.valid_till)],
    ["BOQ Ref.", doc.get("custom_bill_of_quantity")]
]) }}
{{ ap.two_boxes(ap.party_box("Client", p), ap.info_box("Project", [
    ["Project", doc.get("custom_project")],
    ["Location", doc.get("custom_location")],
    ["Subject", doc.get("custom_subject")],
    ["LPO Ref.", doc.get("lpo_ref")]
])) }}
{%- if doc.get("custom_scope_of_work") %}<div class="sec"><div class="sec-title">Scope of Work</div>{{ ap.bullets(doc.custom_scope_of_work) }}</div>{% endif %}
<div class="sec"><div class="sec-title">Summary <span class="ar">الملخص</span></div>{{ ap.boq_summary(groups, doc) }}</div>
<div class="sec" style="page-break-inside:auto"><div class="sec-title">Bill of Quantities <span class="ar">جدول الكميات</span></div>{{ ap.boq_detail(groups, doc) }}</div>
{%- set sched = doc.get("custom_materials_delivery_schedule") or [] %}
{%- if sched %}<div class="sec"><div class="sec-title">Materials Delivery Time</div><ul>{% for r in sched %}<li><b>{{ r.material_description }}:</b> {{ r.delivery_time }}</li>{% endfor %}</ul></div>{% endif %}
{%- set excl = doc.get("custom_exclusions_items") or [] %}
{%- if excl %}<div class="sec"><div class="sec-title">Exclusions</div><ol>{% for r in excl %}<li>{{ r.details }}</li>{% endfor %}</ol></div>{% endif %}
{{ ap.section("Notes", doc.get("terms")) }}
<p class="muted" style="margin-top:8px">Amounts exclude VAT unless stated otherwise.</p>
{{ ap.signatures(c, ["Prepared by", "For " ~ c.name, "Client Approval"], 1) }}
{{ ap.footer(c) }}
</div>
